<script lang="ts">
  import {taskNames,usageAmount,usageCount,usageMonth} from '#lib/client/ai-usage.ts';
  import {refreshAll} from '$app/navigation';
  import {command,request,display} from '#lib/client/api.ts';
  import type {AppData,Row} from '#lib/client/types.ts';
  import Icon from './Icon.svelte';
  import Status from './Status.svelte';
  let {data,configured=false}:{data:AppData;configured?:boolean}=$props();
  let password=$state('');let busy=$state(false);let error=$state('');let notice=$state('');
  let resolving:Row|null=$state(null);let actualCost=$state(''),reconciliationReason=$state(''),reconciliationPassword=$state(''),receiptConfirmed=$state(false);
  const usage=$derived((data.related?.ai_usage as unknown as Row)||{});
  const budget=$derived(usage.budget||{});
  const capabilities=$derived(Array.isArray(usage.tasks)?usage.tasks:[]);
  const totals=$derived(usage.totals||{});
  const currentMonth=new Date().toISOString().slice(0,7);
  const unsettled=$derived(Array.isArray(usage.unsettled)?usage.unsettled:[]);
  const names=taskNames;
  const amount=usageAmount,count=usageCount;
  const remaining=$derived(budget.limit_amount!==undefined&&budget.spent!==undefined&&budget.reserved!==undefined?Math.max(0,Number(budget.limit_amount)-Number(budget.spent)-Number(budget.reserved)):null);
  async function test(event:SubmitEvent){event.preventDefault();if(busy)return;busy=true;error='';notice='';try{await request('/api/v1/reauth',{password});await command('integrations.openai.test',undefined,{});password='';notice='Eine kleine Prüfung mit dem gespeicherten Standardmodell wurde eingereiht. Sie verwendet synthetische Daten und das freigegebene Kostenlimit. Das tatsächliche Ergebnis finden Sie unter Verarbeitung.';await refreshAll().catch(()=>{});}catch(cause){error=cause instanceof Error?cause.message:'Die Modellprüfung konnte nicht gestartet werden.';}finally{busy=false;}}
  function beginReconciliation(row:Row){resolving=row;actualCost='';reconciliationReason='';reconciliationPassword='';receiptConfirmed=false;error='';notice='';}
  async function reconcile(event:SubmitEvent){event.preventDefault();if(!resolving||!receiptConfirmed||busy)return;const run=resolving;busy=true;error='';notice='';try{await request('/api/v1/reauth',{password:reconciliationPassword});await command('integrations.openai.usage.resolve',undefined,{run_id:run.id,actual_cost:actualCost.replace(',','.'),reason:reconciliationReason});resolving=null;reconciliationPassword='';notice='Der belegte tatsächliche Verbrauch wurde abgeglichen und die zugehörige Reservierung aufgelöst.';await refreshAll().catch(()=>{});}catch(cause){error=cause instanceof Error?cause.message:'Die offenen Kosten konnten nicht abgeglichen werden.';}finally{busy=false;}}
</script>
<section class="panel mt" aria-labelledby="ai-usage-title">
  <header class="panel-header usage-header"><div><h2 id="ai-usage-title">KI-Verbrauch & Kosten</h2><p>{usageMonth(usage.period||currentMonth)} · API-Aufrufe dieser Suite · USD</p></div><form method="GET" action="/settings" class="usage-period"><input type="hidden" name="tab" value="usage"/><div class="field"><label for="usage-period">Monat</label><input id="usage-period" name="period" type="month" value={usage.period||currentMonth} min="2000-01" max={currentMonth} required/></div><button class="btn small">Monat anzeigen</button></form></header>
  <div class="panel-body">
    <dl class="definition-list usage-totals"><div><dt>Erfasste Tokens gesamt</dt><dd>{count(totals.total_tokens)}<span class="field-help">{count(totals.input_tokens)} Eingabe · {count(totals.output_tokens)} Ausgabe</span></dd></div><div><dt>Erfasste Kosten</dt><dd>{totals.requests&&totals.missing_cost===totals.requests?'Noch offen':amount(totals.cost)}<span class="field-help">{amount(totals.estimated_cost)} geschätzt · {amount(totals.confirmed_cost)} mit Beleg abgeglichen</span></dd></div><div><dt>API-Aufrufe</dt><dd>{count(totals.requests)}<span class="field-help">{count(totals.rejected)} vom Anbieter abgewiesen</span></dd></div><div><dt>Davon aus dem Anbieter-Cache</dt><dd>{totals.cache_measured?count(totals.cached_tokens):'Nicht erfasst'}<span class="field-help">Bereits in Eingabetokens enthalten</span></dd></div></dl>
    {#if totals.missing_usage||totals.missing_cost}<p class="usage-incomplete" role="status">Noch unvollständig: Bei {count(totals.missing_usage)} Aufrufen fehlen vollständige Tokenangaben, bei {count(totals.missing_cost)} sind die Kosten offen. Diese Beträge sind in der Summe noch nicht enthalten.</p>{/if}
    <p class="field-help mt">Tokens sind die vom Anbieter gemeldeten Verarbeitungseinheiten für Ein- und Ausgabe. Die Kostenschätzung nutzt das beim Aufruf gespeicherte Preisprofil; sie ist keine Anbieterrechnung. Maßgeblich bleibt die <a class="text-link" href="https://platform.openai.com/usage" target="_blank" rel="noreferrer">OpenAI-Verbrauchsübersicht</a>.</p>
  </div>
  {#if capabilities.length}
    <!-- svelte-ignore a11y_no_noninteractive_tabindex (Keyboard access to horizontally scrolling data.) -->
    <div class="table-scroll" tabindex="0" role="region" aria-label="Verbrauch nach Aufgabe und Modell"><table class="data-table usage-table"><caption>Welche Aufgaben verbrauchen wie viel?</caption><thead><tr><th>Aufgabe / Modell</th><th class="number">Aufrufe</th><th class="number">Eingabetokens</th><th class="number">Ausgabetokens</th><th class="number">Kosten · USD</th></tr></thead><tbody>{#each capabilities as row}<tr><th scope="row">{names[row.task_type]||'Weitere KI-Aufgabe'}<span class="record-subtitle">{row.model_id}</span>{#if row.missing_usage||row.missing_cost}<span class="record-subtitle">{row.missing_usage?row.missing_usage+' × Tokens offen':''}{row.missing_usage&&row.missing_cost?' · ':''}{row.missing_cost?row.missing_cost+' × Kosten offen':''}</span>{/if}</th><td class="number">{count(row.requests)}</td><td class="number">{count(row.input_tokens)}</td><td class="number">{count(row.output_tokens)}</td><td class="number">{row.missing_cost===row.requests?'Noch offen':amount(row.cost)}<span class="record-subtitle">{Number(row.confirmed_cost)>0?'Mit abgeglichenen Belegen':'Geschätzt'}</span></td></tr>{/each}</tbody></table></div>
  {:else}<div class="panel-body usage-empty"><h3>Noch keine KI-Aufrufe in diesem Monat</h3><p>Wenn Sie den Assistenten, die Spracheingabe oder KI-Bilder nutzen, erscheint der Verbrauch hier automatisch. Einen früheren Monat können Sie oben auswählen.</p></div>{/if}
  <div class="panel-body usage-notes"><p class="field-help">Ältere Assistentenaufrufe bleiben gemeinsam ausgewiesen, wenn ihre genaue Aufgabenart nicht gespeichert wurde. Wiederverwendete Antworten aus der Suite lösen keinen neuen API-Aufruf aus. Technische 3D-Renderings ohne OpenAI sind hier nicht enthalten. Abgrenzung der Monate: UTC.</p><details><summary>Monatsbudget und offene Reservierungen</summary><dl class="definition-list mt"><div><dt>Freigegebenes Monatsbudget</dt><dd>{budget.limit_amount!=null?amount(budget.limit_amount):'Noch nicht eingerichtet'}</dd></div><div><dt>Verbuchter Verbrauch · geschätzt / abgeglichen</dt><dd>{amount(budget.spent)}</dd></div><div><dt>Für offene Aufrufe reserviert</dt><dd>{amount(budget.reserved)}</dd></div><div><dt>Noch verfügbares Budget</dt><dd>{amount(remaining)}</dd></div></dl><p class="field-help mt">Reservierungen sind mögliche Kosten noch nicht abgeschlossener Aufrufe. Ein unklarer Ausgang bleibt bis zum Abgleich reserviert. Die Budgeteinstellung erreichen Sie unter <a class="text-link" href="/settings?tab=integrations">Integrationen</a>.</p></details></div>
  {#if unsettled.length}<div class="panel-body"><h3 class="small">Offene Aufrufe · alle Monate, höchstens 30 angezeigt</h3>{#each unsettled as row}<article class="ai-unsettled"><div><strong>{names[row.task_type||row.capability]||'KI-Funktion'} · {row.model_id}</strong><p>{display(row.created_at,'created_at')} · reservierte Obergrenze {amount(row.cost_reserved)}</p></div><Status value={row.status}/>{#if ['outcome_unknown','cost_review'].includes(row.status)}<button class="btn small" disabled={busy} onclick={()=>beginReconciliation(row)}>Anbieterbeleg abgleichen</button>{/if}</article>{/each}<p class="field-help mt">Diese Kosten sind nicht als null verbucht. Prüfen Sie unklare Aufrufe im Anbieterprojekt und im Verarbeitungsnachweis, bevor Sie dieselbe Aufgabe erneut kostenpflichtig starten.</p></div>{/if}
  {#if resolving}<form class="panel-body ai-reconciliation" onsubmit={reconcile}><h3>Belegte Kosten eines ungeklärten Aufrufs</h3><p class="small mt">{resolving.model_id} · gestartet {display(resolving.created_at,'created_at')}. Gleichen Sie den konkreten Aufruf mit dem tatsächlichen Nachweis im Anbieterprojekt ab.</p><div class="field-grid mt"><div class="field"><label for="ai-actual-cost">Belegte tatsächliche Kosten · USD *</label><input id="ai-actual-cost" inputmode="decimal" bind:value={actualCost} required pattern="[0-9]+([,.][0-9]+)?"/><span class="field-help">Null nur eintragen, wenn der Anbieter für genau diesen Aufruf keine Kosten bestätigt hat. Eine fehlende Antwort ist kein Kostenbeleg.</span></div><div class="field full"><label for="ai-reconciliation-reason">Anbieterbeleg und konkrete Prüfergebnisse *</label><textarea id="ai-reconciliation-reason" bind:value={reconciliationReason} required minlength="20" placeholder="Belegdatum, Projekt, konkrete Anfrage und bestätigter Verbrauch"></textarea></div><label class="check-field full"><input type="checkbox" bind:checked={receiptConfirmed} required/><span>Ich habe den Anbieterbeleg für diesen konkreten Aufruf kontrolliert. Der eingetragene Betrag ist tatsächlich bestätigt.</span></label><div class="field full"><label for="ai-reconciliation-password">Eigene Passphrase erneut bestätigen *</label><input id="ai-reconciliation-password" type="password" bind:value={reconciliationPassword} autocomplete="current-password" required/></div></div><div class="inline-actions mt"><button class="btn" type="button" disabled={busy} onclick={()=>resolving=null}>Zurück</button><button class="btn primary" disabled={busy||!receiptConfirmed}>Belegten Verbrauch verbindlich abgleichen</button></div>{#if error}<p class="field-error mt" role="alert">{error}</p>{/if}</form>{/if}
  <details class="usage-connection"><summary>Verbindung prüfen · kostenpflichtiger Test</summary><form class="ai-test-form" onsubmit={test}><div><h3>Verbindung praktisch prüfen</h3><p class="small">Startet bewusst genau eine kleine Anfrage mit dem gespeicherten Standardmodell. Dafür gelten die zuvor gespeicherten USD-Kostenlimits.</p>{#if error}<p class="field-error mt" role="alert">{error}</p>{/if}{#if notice}<p class="field-help mt" role="status">{notice}</p>{/if}<div class="field mt"><label for="ai-test-password">Ihr eigenes Suite-Passwort bestätigen *</label><input id="ai-test-password" type="password" autocomplete="current-password" bind:value={password} required/></div></div><button class="btn" disabled={busy||!configured}><Icon name={busy?'refresh':'spark'} size={15} class={busy?'spin':''}/>{busy?'Wird eingereiht …':'Kleine Modellprüfung starten'}</button></form></details>
</section>
<style>.usage-header{flex-wrap:wrap;gap:24px}.usage-period{display:flex;align-items:flex-end;gap:12px}.usage-period .field{margin:0}.usage-period input{min-height:40px}.usage-totals dd{font-variant-numeric:tabular-nums}.usage-totals .field-help{font-size:12px;font-weight:400;display:block;margin-top:8px;max-width:38ch}.usage-incomplete{margin-top:24px;font-size:13px;line-height:1.6}.usage-table{min-width:680px}.usage-table caption{text-align:left;padding:20px 28px 12px;font-size:15px;font-weight:550;color:var(--text)}.usage-table th:first-child{min-width:210px}.usage-table .record-subtitle{display:block;margin-top:6px;font-weight:400;overflow-wrap:anywhere;white-space:normal;max-width:35ch}.usage-empty{border-top:1px solid var(--line)}.usage-empty h3{font-size:16px;font-weight:550}.usage-empty p{max-width:65ch;font-size:14px;line-height:1.7;margin-top:10px}.usage-notes{border-top:1px solid var(--line)}.usage-notes details{margin-top:24px}.usage-notes summary,.usage-connection summary{cursor:pointer;font-size:14px;font-weight:550;min-height:44px;align-content:center}.usage-connection{border-top:1px solid var(--line)}.usage-connection>summary{padding:16px 28px}.usage-connection .ai-test-form{border-top:0}@media(max-width:760px){.usage-period{width:100%;flex-wrap:wrap}.usage-period .field{flex:1;min-width:150px}.usage-period input{width:100%}.usage-table caption{padding-left:20px}.usage-connection>summary{padding:16px 20px}}.ai-unsettled{display:flex;gap:20px;justify-content:space-between;align-items:flex-start;margin-top:20px;padding-top:20px;border-top:1px solid var(--line)}.ai-unsettled strong{font-size:13px;font-weight:550}.ai-unsettled p{font-size:12px;margin-top:6px}.ai-test-form{border-top:1px solid var(--line);padding:26px 28px;background:var(--wash);display:flex;gap:26px;align-items:flex-end}.ai-test-form>div{flex:1;max-width:65ch}.ai-test-form h3{font-size:14px;font-weight:550}.ai-test-form p{margin-top:8px}.ai-test-form .btn{flex:none}@media(max-width:760px){.ai-test-form{padding:24px 20px;flex-direction:column;align-items:stretch}.ai-unsettled{flex-wrap:wrap}.ai-unsettled p{font-size:13px}}.ai-reconciliation{border-top:1px solid var(--line)}.ai-reconciliation h3{font-size:16px;font-weight:550}.ai-unsettled .btn{white-space:normal;max-width:150px}</style>
